PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (user_id TEXT PRIMARY KEY, occupation TEXT NOT NULL, age_group TEXT NOT NULL, monthly_income REAL NOT NULL, current_savings REAL NOT NULL, language TEXT NOT NULL, region TEXT NOT NULL, city TEXT NOT NULL, account_age_days INTEGER NOT NULL, average_monthly_transactions REAL NOT NULL, display_name TEXT NOT NULL DEFAULT '', is_imported INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS import_batches (import_id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(user_id), filename TEXT NOT NULL, fingerprint TEXT NOT NULL UNIQUE, row_count INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transactions (transaction_id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(user_id), timestamp TEXT NOT NULL, amount REAL NOT NULL, transaction_type TEXT NOT NULL, category TEXT NOT NULL, merchant TEXT NOT NULL, device_type TEXT NOT NULL, location TEXT NOT NULL, channel TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_transactions_user_date ON transactions(user_id, timestamp);
CREATE INDEX IF NOT EXISTS ix_transactions_user_category_date ON transactions(user_id, category, timestamp);
CREATE INDEX IF NOT EXISTS ix_transactions_user_type_date ON transactions(user_id, transaction_type, timestamp);
CREATE INDEX IF NOT EXISTS ix_import_batches_user ON import_batches(user_id);
CREATE TABLE IF NOT EXISTS monthly_features (user_id TEXT NOT NULL REFERENCES users(user_id), month TEXT NOT NULL, income REAL NOT NULL, total_expense REAL NOT NULL, food_expense REAL NOT NULL, shopping_expense REAL NOT NULL, transport_expense REAL NOT NULL, entertainment_expense REAL NOT NULL, bill_expense REAL NOT NULL, cashout_expense REAL NOT NULL, other_expense REAL NOT NULL, transaction_count INTEGER NOT NULL, average_transaction REAL NOT NULL, previous_month_expense REAL NOT NULL, rolling_3m_expense REAL NOT NULL, month_number INTEGER NOT NULL, season_sin REAL NOT NULL, season_cos REAL NOT NULL, PRIMARY KEY(user_id, month));
CREATE TABLE IF NOT EXISTS goals (goal_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL REFERENCES users(user_id), goal_name TEXT NOT NULL, target_amount REAL NOT NULL CHECK(target_amount>0), current_saved_amount REAL NOT NULL CHECK(current_saved_amount>=0), target_months INTEGER NOT NULL CHECK(target_months BETWEEN 1 AND 36), deadline TEXT, priority TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS goal_contributions (contribution_id INTEGER PRIMARY KEY AUTOINCREMENT, goal_id INTEGER NOT NULL REFERENCES goals(goal_id), amount REAL NOT NULL CHECK(amount>0), note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_goals_user_latest ON goals(user_id, goal_id DESC);
CREATE INDEX IF NOT EXISTS ix_contributions_goal_date ON goal_contributions(goal_id, created_at);
CREATE TABLE IF NOT EXISTS goal_plans (plan_id INTEGER PRIMARY KEY AUTOINCREMENT, goal_id INTEGER NOT NULL REFERENCES goals(goal_id), plan_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS recommendations (recommendation_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL REFERENCES users(user_id), kind TEXT NOT NULL, text_en TEXT NOT NULL, text_bn TEXT NOT NULL, reason_en TEXT NOT NULL, reason_bn TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS model_metrics (metric_key TEXT PRIMARY KEY, value_json TEXT NOT NULL);
